import { Component, signal } from '@angular/core';

@Component({
  selector: 'app-binding-demo',
  standalone: true,
  template: `
    <div>
      <!-- 1. Interpolation: Hiển thị chuỗi văn bản -->
      <p>Xin chào, {{ userName() }}!</p>

      <!-- 2. Property Binding: Gán boolean trực tiếp vào DOM property disabled -->
      <button [disabled]="isSubmitting()" (click)="handleSubmit($event)">
        Submit
      </button>

      <!-- 3. Event Binding: Lắng nghe sự kiện input và truyền $event -->
      <input [value]="userName()" (input)="onInputChanged($event)" />
    </div>
  `
})
export class BindingDemoComponent {
  readonly userName = signal<string>('Alex');
  readonly isSubmitting = signal<boolean>(false);

  handleSubmit(event: MouseEvent): void {
    console.log('Button clicked at coordinates:', event.clientX, event.clientY);
    this.isSubmitting.set(true);
  }

  onInputChanged(event: Event): void {
    const target = event.target as HTMLInputElement;
    this.userName.set(target.value);
  }
}

