import { Component, input, output, computed } from '@angular/core';

@Component({
  selector: 'app-pagination',
  standalone: true,
  template: `
    <div class="pagination-bar">
      <button [disabled]="isFirstPage()" (click)="prevPage()">Trang trước</button>
      <span>Trang {{ currentPage() }} / {{ totalPages() }}</span>
      <button [disabled]="isLastPage()" (click)="nextPage()">Trang sau</button>
    </div>
  `
})
export class PaginationComponent {
  // Signal Inputs: An toàn kiểu, tự động cập nhật phản ứng
  readonly currentPage = input.required<number>();
  readonly totalPages = input<number>(1);

  // Signal Output: Phát sự kiện lên cha
  readonly pageChange = output<number>();

  // Computed signals phái sinh tự động từ inputs
  readonly isFirstPage = computed(() => this.currentPage() <= 1);
  readonly isLastPage = computed(() => this.currentPage() >= this.totalPages());

  prevPage(): void {
    if (!this.isFirstPage()) this.pageChange.emit(this.currentPage() - 1);
  }

  nextPage(): void {
    if (!this.isLastPage()) this.pageChange.emit(this.currentPage() + 1);
  }
}

import { Directive, ElementRef, HostListener, Input, inject } from '@angular/core';

// Attribute Directive: Đổi màu nền khi di chuột
@Directive({
  selector: '[appHighlight]',
  standalone: true
})
export class HighlightDirective {
  private readonly el = inject(ElementRef);

  @Input('appHighlight') highlightColor: string = '#fef08a';

  @HostListener('mouseenter')
  onMouseEnter(): void {
    this.setBackground(this.highlightColor);
  }

  @HostListener('mouseleave')
  onMouseLeave(): void {
    this.setBackground('');
  }

  private setBackground(color: string): void {
    this.el.nativeElement.style.backgroundColor = color;
  }
}

