import { Component, signal, computed, effect } from '@angular/core';

@Component({
  selector: 'app-cart-summary',
  standalone: true,
  template: `
    <div>
      <h3>Giỏ hàng</h3>
      <p>Đơn giá: {{ price() }}đ | Số lượng: {{ quantity() }}</p>
      <p><strong>Tổng tiền: {{ totalPrice() }}đ</strong></p>
      <button (click)="increaseQuantity()">Thêm 1 món</button>
    </div>
  `
})
export class CartSummaryComponent {
  // 1. Writable Signals
  readonly price = signal<number>(50000);
  readonly quantity = signal<number>(2);

  // 2. Computed Signal: Tự động cập nhật và cache
  readonly totalPrice = computed(() => this.price() * this.quantity());

  constructor() {
    // 3. Effect: Ghi log side-effect
    effect(() => {
      console.log(`[Analytics] Giỏ hàng đổi: ${this.quantity()} món, Tổng: ${this.totalPrice()}đ`);
    });
  }

  increaseQuantity(): void {
    this.quantity.update(q => q + 1);
  }
}

