  @Input() userId!: string;
  user: any = null;

  // 1. Constructor: CHỈ dùng để khởi tạo biến cơ bản, KHÔNG gọi side-effect
  constructor() {
    // SAI NẾU GỌI: this.userService.getUser(this.userId) => userId lúc này là undefined!
