  standalone: true,
  template: `
    <div>
      <button (click)="addWrong()">Thêm sai (In-place)</button>
      <button (click)="addCorrect()">Thêm đúng (Immutability update)</button>
      <ul>
        <li *ngFor="let item of items()">{{ item }}</li>
      </ul>
    </div>
  `
})
export class TodoListComponent {
  readonly items = signal<string[]>(['Học Angular', 'Học Signals']);

  // SAI LẦM: Không trigger UI re-render vì tham chiếu mảng không đổi
  addWrong(): void {
    this.items().push('Task mới'); // Signal không nhận biết được thay đổi!
  }

  // ĐÚNG: Dùng .update() trả về mảng bất biến mới
  addCorrect(): void {
    this.items.update(list => [...list, `Task #${list.length + 1}`]);
  }
}

