  private timerId?: number;

  ngOnInit(): void {
    console.log('1. ngOnInit: Khởi tạo dữ liệu');
    this.timerId = window.setInterval(() => console.log('Polling...'), 10000);
  }

  ngAfterViewInit(): void {
