import { Component, input, computed, booleanAttribute } from '@angular/core';

@Component({
  selector: 'app-product-card',
  standalone: true,
  template: `
    <div class="card" [class.highlight]="isFeatured()">
      <h3>{{ title() }}</h3>
      <p>Giá: {{ formattedPrice() }}</p>
    </div>
  `
})
export class ProductCardComponent {
  // 1. Required input: Báo lỗi compile nếu cha không truyền
  readonly title = input.required<string>();
  readonly rawPrice = input.required<number>();

  // 2. Input với transform tự động ép kiểu boolean attribute (ví dụ <app-product-card isFeatured />)
  readonly isFeatured = input(false, { transform: booleanAttribute });

  // 3. Computed tự động đồng bộ khi rawPrice thay đổi
  readonly formattedPrice = computed(() =>
    new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(this.rawPrice())
  );
}

