import { Component, signal } from '@angular/core';

interface Task {
  id: string;
  name: string;
  status: 'PENDING' | 'DONE';
}

@Component({
  selector: 'app-task-board',
  standalone: true,
  // KHÔNG CẦN import CommonModule hay NgFor/NgIf!
  template: `
    <div>
      <!-- @if - @else if - @else rõ ràng như ngôn ngữ lập trình -->
      @if (isLoading()) {
        <p>Đang tải dữ liệu...</p>
      } @else if (tasks().length > 0) {
        <ul>
          <!-- @for bắt buộc có track; hỗ trợ khối @empty tự nhiên -->
          @for (task of tasks(); track task.id; let idx = $index, count = $count) {
            <li>
              {{ idx + 1 }}/{{ count }}: {{ task.name }}
              @switch (task.status) {
                @case ('PENDING') { <span class="badge-yellow">Chờ</span> }
                @case ('DONE') { <span class="badge-green">Xong</span> }
              }
            </li>
          } @empty {
            <p>Không có nhiệm vụ nào được giao!</p>
          }
        </ul>
      }
    </div>
  `
})
export class TaskBoardComponent {
  readonly isLoading = signal(false);
  readonly tasks = signal<Task[]>([
    { id: 'tk_1', name: 'Viết unit tests', status: 'DONE' },
    { id: 'tk_2', name: 'Refactor Control Flow', status: 'PENDING' }
  ]);
}

