@Component({
  selector: 'app-user-list',
  standalone: true,
  template: `
    <div>
      <button (click)="reorderList()">Đảo ngược danh sách</button>
      <ul>
        <!-- ĐÚNG: track theo thuộc tính id duy nhất -->
        @for (user of users(); track user.id) {
          <li>
            <span>{{ user.name }}</span>
            <!-- Input giữ nguyên nội dung gõ dở nhờ track chính xác -->
            <input placeholder="Ghi chú tạm thời..." />
          </li>
        }
      </ul>
    </div>
  `
})
export class UserListComponent {
  readonly users = signal<UserItem[]>([
    { id: 'usr_1', name: 'Alice' },
    { id: 'usr_2', name: 'Bob' },
    { id: 'usr_3', name: 'Charlie' }
  ]);

  reorderList(): void {
    // Chỉ hoán đổi vị trí mảng, Angular sẽ chỉ di chuyển DOM node mà không hủy tạo lại
    this.users.update(list => [...list].reverse());
  }
}

