  readonly price = signal<number>(100000);
  readonly quantity = signal<number>(1);

  // 2. COMPUTED: Derived state tự động tính toán và cache
  readonly total = computed(() => this.price() * this.quantity());

  constructor() {
    // 3. EFFECT: Side-effect đồng bộ trạng thái ra ngoài
    effect((onCleanup) => {
      const currentTotal = this.total();
      console.log(`[Effect] Cập nhật tổng tiền vào LocalStorage: ${currentTotal}`);
      localStorage.setItem('cart_total', currentTotal.toString());

      onCleanup(() => {
        console.log('[Effect Cleanup] Chạy trước khi effect re-run');
      });
    });
  }

  add(): void {
    this.quantity.update(q => q + 1);
  }
}

