Angular cung cấp 4 chiến lược cấu hình Provider:
1) `useClass`: Khởi tạo một class cụ thể khi token được yêu cầu (thường dùng để tráo đổi implementation, vd: `useClass: MockAuthService`);
2) `useValue`: Cung cấp trực tiếp một giá trị tĩnh hoặc plain object (dùng cho config, hằng số);
3) `useFactory`: Thực thi một hàm factory để tạo ra instance dựa trên logic điều kiện hoặc các dependencies phụ thuộc;
4) `useExisting`: Tạo một bí danh (alias) trỏ tới một provider đã tồn tại sẵn, tránh việc tạo ra hai instance riêng biệt.

seniorAnswer.codeExample:
import { Component, Injectable, InjectionToken, inject } from '@angular/core';

export abstract class LoggerService {
  abstract log(msg: string): void;
}

@Injectable({ providedIn: 'root' })
export class ConsoleLoggerService extends LoggerService {
  log(msg: string) { console.log('[Console]:', msg); }
}

@Injectable({ providedIn: 'root' })
export class FileLoggerService extends LoggerService {
  log(msg: string) { console.log('[File]:', msg); }
}

export const IS_PRODUCTION = new InjectionToken<boolean>('IS_PROD');

// Đăng ký linh hoạt thông qua các Provider Strategies
export const loggerProviders = [
  // 1. useValue: Giá trị boolean tĩnh
  { provide: IS_PRODUCTION, useValue: true },

  // 2. useFactory: Khởi tạo service theo điều kiện runtime
  {
    provide: LoggerService,
    useFactory: () => {
      const isProd = inject(IS_PRODUCTION);
      return isProd ? new FileLoggerService() : new ConsoleLoggerService();
    }
  },

  // 3. useExisting: Alias không tạo instance mới
  { provide: 'LegacyLoggerAlias', useExisting: LoggerService }
];

