import { Component, OnInit, inject, signal } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

@Component({
  selector: 'app-article-view',
  standalone: true,
  template: `<p>Đang xem bài viết ID: {{ currentId() }}</p>`
})
export class ArticleViewComponent {
  private readonly route = inject(ActivatedRoute);
  readonly currentId = signal<string>('');

  constructor() {
    // ĐÚNG: Lắng nghe paramMap dạng Observable để cập nhật khi URL đổi params
    this.route.paramMap.pipe(takeUntilDestroyed()).subscribe(params => {
      const id = params.get('id');
      if (id) this.currentId.set(id);
    });

    // Đọc query param (?sort=desc)
    this.route.queryParamMap.pipe(takeUntilDestroyed()).subscribe(queries => {
      console.log('Sort order:', queries.get('sort'));
    });
  }
}

