import { AbstractControl, ValidationErrors, ValidatorFn, FormGroup, FormControl } from '@angular/forms';

// 1. Validator kiểm tra chéo: Xác nhận mật khẩu khớp nhau
export const passwordMatchValidator: ValidatorFn = (control: AbstractControl): ValidationErrors | null => {
  const password = control.get('password')?.value;
  const confirmPassword = control.get('confirmPassword')?.value;

  // Nếu chưa nhập đủ 2 trường thì không báo lỗi match
  if (!password || !confirmPassword) {
    return null;
  }

  // Trả về null nếu hợp lệ, ngược lại trả về object lỗi
  return password === confirmPassword ? null : { passwordMismatch: true };
};

