import { debounceTime, distinctUntilChanged, switchMap, exhaustMap } from 'rxjs';

@Component({
  selector: 'app-search-and-submit',
  standalone: true,
  imports: [ReactiveFormsModule],
  template: `
    <div>
      <!-- Use-case 1: Autocomplete dùng switchMap -->
