import { Component, inject, OnInit } from '@angular/core';
import { interval } from 'rxjs';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

@Component({
  selector: 'app-leak-free',
  standalone: true,
  template: `<p>Component an toàn không rò rỉ bộ nhớ</p>`
})
export class LeakFreeComponent {
  // 1. CHUẨN HIỆN ĐẠI: takeUntilDestroyed tự động dọn dẹp trong constructor
  private readonly timer$ = interval(1000).pipe(
    takeUntilDestroyed()
  ).subscribe(val => {
    console.log('Timer tick:', val);
  });

  // Lưu ý với HttpClient: HttpClient tự complete sau 1 response nên ít nguy cơ leak hơn,
  // nhưng vẫn nên dùng takeUntilDestroyed để hủy request nếu user rời trang giữa chừng!
}

