// 1. interceptors/error.interceptor.ts - Xử lý lỗi toàn cục
import { HttpInterceptorFn, HttpErrorResponse } from '@angular/common/http';
import { inject } from '@angular/core';
import { Router } from '@angular/router';
import { catchError, throwError } from 'rxjs';

export const globalErrorInterceptor: HttpInterceptorFn = (req, next) => {
  const router = inject(Router);

  return next(req).pipe(
    catchError((error: HttpErrorResponse) => {
      if (error.status === 401) {
        console.warn('[HTTP 401] Phiên làm việc hết hạn, chuyển về login');
        router.navigate(['/login']);
      } else if (error.status >= 500) {
        console.error('[HTTP 500] Máy chủ gặp sự cố:', error.message);
      }
      // Ném lỗi tiếp cho Service/Component xử lý nếu cần
      return throwError(() => error);
    })
  );
};

