import { Injectable, signal, computed } from '@angular/core';

export interface Todo { id: string; title: string; completed: boolean; }

@Injectable({ providedIn: 'root' })
export class TodoStateService {
  // State
  readonly #todos = signal<Todo[]>([]);

  // Selectors (Getters)
  readonly todos = this.#todos.asReadonly();
  readonly completedCount = computed(() => this.#todos().filter(t => t.completed).length);

  // Actions
  addTodo(title: string): void {
    this.#todos.update(list => [...list, { id: crypto.randomUUID(), title, completed: false }]);
  }

  toggleTodo(id: string): void {
    this.#todos.update(list => list.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  }
}

