import { Component, signal } from '@angular/core';
// resource API mới từ Angular 19 (@angular/core)
import { resource } from '@angular/core';

interface ProductItem {
  id: string;
  name: string;
  price: number;
}

@Component({
  selector: 'app-product-search',
  standalone: true,
  template: `
    <div>
      <input [value]="query()" (input)="query.set($any($event.target).value)" />

      @if (productResource.isLoading()) {
        <p>Đang tìm kiếm sản phẩm...</p>
      } @else if (productResource.error()) {
        <p class="error">Lỗi: {{ productResource.error() }}</p>
      } @else if (productResource.value(); as products) {
        <ul>
          @for (p of products; track p.id) { <li>{{ p.name }} - {{ p.price }}đ</li> }
        </ul>
      }
      <button (click)="productResource.reload()">Tải lại dữ liệu</button>
    </div>
  `
})
export class ProductSearchComponent {
  readonly query = signal<string>('phone');

  // Angular 19 resource: Tự động theo dõi query() và hủy request bằng AbortSignal
  readonly productResource = resource<ProductItem[], { q: string }>({
    request: () => ({ q: this.query() }),
    loader: async ({ request, abortSignal }) => {
      const response = await fetch(`/api/products?q=${encodeURIComponent(request.q)}`, {
        signal: abortSignal
      });
      if (!response.ok) throw new Error('Không thể tải sản phẩm');
      return response.json();
    }
  });
}

