@Component({
  selector: 'app-star-rating',
  standalone: true,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => StarRatingComponent),
      multi: true
    }
  ],
  template: `
    <div class="stars-wrapper" [class.disabled]="isDisabled()">
      @for (star of [1, 2, 3, 4, 5]; track star) {
