export class StarRatingComponent implements ControlValueAccessor {
  readonly value = signal<number>(0);
  readonly isDisabled = signal<boolean>(false);

  private onChange: (val: number) => void = () => {};
  private onTouched: () => void = () => {};

  // 1. Angular đẩy giá trị vào
  writeValue(val: number): void {
    this.value.set(val || 0);
  }

  // 2. Lưu callback onChange
  registerOnChange(fn: any): void {
    this.onChange = fn;
  }

  // 3. Lưu callback onTouched
  registerOnTouched(fn: any): void {
    this.onTouched = fn;
  }

  // 4. Angular disable control
  setDisabledState(isDisabled: boolean): void {
    this.isDisabled.set(isDisabled);
  }

  // Khi user click chọn sao trên giao diện
  selectRating(rating: number): void {
    if (this.isDisabled()) return;
    this.value.set(rating);
    this.onChange(rating); // Báo giá trị ra cho Reactive Form
    this.onTouched();      // Đánh dấu touched
  }
}

